mapper.select:
SELECT id FROM orders WHERE status = 'PENDING_PAYMENT' AND expires_at <= #{now}
  AND expiry_retry_at <= #{now}
ORDER BY expires_at, id LIMIT #{limit}

mapper.update:
UPDATE orders SET expiry_retry_attempts = LEAST(expiry_retry_attempts + 1, 30),
  expiry_retry_at = #{retryAt}
WHERE id = #{id} AND status = 'PENDING_PAYMENT'
